// src/adapters/r2-avatar-store.ts
function r2AvatarStore(bucket) {
  const path = (key) => `core/avatars/${key}`;
  return {
    async put(key, bytes, contentType) {
      await bucket.put(path(key), bytes, { httpMetadata: { contentType } });
    },
    async get(key) {
      const object2 = await bucket.get(path(key));
      return object2 ? { body: object2.body, contentType: object2.httpMetadata?.contentType ?? "application/octet-stream" } : null;
    },
    async delete(key) {
      await bucket.delete(path(key));
    }
  };
}

