// src/routes/avatar.ts
function registerAvatarRoutes(app2, dependencies) {
  app2.put("/api/me/avatar", async (c) => {
    const input2 = await readAvatar(c.req.raw);
    if ("error" in input2) return c.json({ error: input2.error }, input2.status);
    const store = avatarStore(c.env, dependencies);
    if (!store) return c.json({ error: "\u5934\u50CF\u5B58\u50A8\u5C1A\u672A\u914D\u7F6E" }, 503);
    const uid = c.get("session").uid;
    const previous = await getProfileIdentity(c.env.CORE_DB, uid);
    if (!previous) return c.json({ error: "\u7528\u6237\u4E0D\u53EF\u7528" }, 403);
    const key = crypto.randomUUID();
    try {
      await store.put(key, input2.bytes, input2.contentType);
    } catch {
      return c.json({ error: "\u5934\u50CF\u4E0A\u4F20\u5931\u8D25\uFF0C\u8BF7\u91CD\u8BD5" }, 503);
    }
    let committed = false;
    try {
      const result = await c.env.CORE_DB.prepare(
        "UPDATE users SET avatar_key = ?, profile_revision = profile_revision + 1 WHERE id = ? AND status = ? AND avatar_key IS ?"
      ).bind(key, uid, "active", previous.avatarKey).run();
      committed = (result.meta.changes ?? 0) > 0;
      if (!committed) return c.json({ error: "\u8D44\u6599\u5DF2\u5728\u5176\u4ED6\u7A97\u53E3\u66F4\u65B0\uFF0C\u8BF7\u91CD\u8BD5" }, 409);
    } catch {
      return c.json({ error: "\u5934\u50CF\u4FDD\u5B58\u5931\u8D25\uFF0C\u8BF7\u91CD\u8BD5" }, 503);
    } finally {
      const obsolete = committed ? previous.avatarKey : key;
      if (obsolete) await store.delete(obsolete).catch(() => console.warn("profile avatar cleanup failed"));
    }
    return c.json({ avatarUrl: profileAvatarUrl(c.req.url, key) });
  });
  app2.delete("/api/me/avatar", async (c) => {
    const uid = c.get("session").uid;
    const previous = await getProfileIdentity(c.env.CORE_DB, uid);
    if (!previous) return c.json({ error: "\u7528\u6237\u4E0D\u53EF\u7528" }, 403);
    const store = avatarStore(c.env, dependencies);
    if (!store && previous.avatarKey) return c.json({ error: "\u5934\u50CF\u5B58\u50A8\u5C1A\u672A\u914D\u7F6E" }, 503);
    const result = await c.env.CORE_DB.prepare(
      "UPDATE users SET avatar_key = ?, profile_revision = profile_revision + 1 WHERE id = ? AND status = ? AND avatar_key IS ?"
    ).bind("", uid, "active", previous.avatarKey).run();
    if (!(result.meta.changes ?? 0)) return c.json({ error: "\u8D44\u6599\u5DF2\u5728\u5176\u4ED6\u7A97\u53E3\u66F4\u65B0\uFF0C\u8BF7\u91CD\u8BD5" }, 409);
    if (previous.avatarKey) await store.delete(previous.avatarKey).catch(() => console.warn("profile avatar cleanup failed"));
    return c.json({ avatarUrl: "" });
  });
  app2.get("/api/avatars/:key", async (c) => {
    const key = c.req.param("key");
    if (!/^[a-f0-9-]{36}$/.test(key)) return c.json({ error: "\u5934\u50CF\u4E0D\u5B58\u5728" }, 404);
    const owner = await c.env.CORE_DB.prepare("SELECT id FROM users WHERE avatar_key = ? AND status = ?").bind(key, "active").first();
    if (!owner) return c.json({ error: "\u5934\u50CF\u4E0D\u5B58\u5728" }, 404);
    const store = avatarStore(c.env, dependencies);
    if (!store) return c.json({ error: "\u5934\u50CF\u5B58\u50A8\u5C1A\u672A\u914D\u7F6E" }, 503);
    try {
      const object2 = await store.get(key);
      if (!object2) return c.json({ error: "\u5934\u50CF\u4E0D\u5B58\u5728" }, 404);
      return new Response(object2.body, { headers: {
        "content-type": object2.contentType,
        "cache-control": "private, max-age=86400, immutable",
        "x-content-type-options": "nosniff"
      } });
    } catch {
      return c.json({ error: "\u5934\u50CF\u6682\u65F6\u4E0D\u53EF\u7528" }, 503);
    }
  });
}

// src/routes/profile.ts
function registerProfileRoutes(app2, dependencies) {
  app2.get("/api/me", async (c) => {
    const session = c.get("session");
    const member = c.get("member");
    const profile = await getProfileIdentity(c.env.CORE_DB, session.uid);
    const mail = await readMailAccess(c.env.CORE_DB);
    return c.json({
      authenticated: true,
      user: { id: session.uid, name: profile?.name ?? session.name, issuer: session.iss, sub: session.sub, role: member.role, avatarUrl: profileAvatarUrl(c.req.url, profile?.avatarKey) },
      avatarUploadEnabled: Boolean(avatarStore(c.env, dependencies)),
      mailEnabled: mail.enabled,
      mailPortalUrl: mail.portalUrl
    });
  });
  app2.patch("/api/me", async (c) => {
    const body = await c.req.json().catch(() => null);
    const name = typeof body?.name === "string" ? body.name.trim() : "";
    if (!name || name.length > 80) return c.json({ error: "\u6635\u79F0\u9700\u4E3A 1-80 \u4E2A\u5B57\u7B26" }, 400);
    const session = c.get("session");
    if (!await updateDisplayName(c.env.CORE_DB, session.uid, name)) return c.json({ error: "\u7528\u6237\u4E0D\u53EF\u7528" }, 404);
    return c.json({ name });
  });
}

