async function consumeSetupToken(db, token, usedBy) {
  const result = await db.prepare("UPDATE setup_tokens SET used_at = datetime('now'), used_by = ? WHERE token = ? AND used_at IS NULL").bind(usedBy, token).run();
  return result.meta.changes > 0;
}
async function releaseSetupToken(db, token, usedBy) {
  const result = await db.prepare("UPDATE setup_tokens SET used_at = NULL, used_by = NULL WHERE token = ? AND used_by = ? AND used_at IS NOT NULL").bind(token, usedBy).run();
  return result.meta.changes > 0;
}
async function isSetupTokenValid(db, token) {
  const row = await db.prepare("SELECT 1 AS ok FROM setup_tokens WHERE token = ? AND used_at IS NULL").bind(token).first();
  return Boolean(row);
}

