    if (taken) {
      return c.json({ error: "\u8BE5\u7528\u6237\u540D\u5DF2\u88AB\u5360\u7528" }, 409);
    }
    const passwordHash = await buildStoredCredential(salt, proof);
    const userId = `u_${crypto.randomUUID().replace(/-/g, "")}`;
