// src/index.ts
function createApp(dependencies = {}) {
  const app2 = new Hono2();
  app2.use("*", async (c, next) => {
    const requestId = `req-${crypto.randomUUID().replace(/-/g, "").slice(0, 16)}`;
    await next();
    c.header("x-request-id", requestId);
  });
  app2.use("/api/me", requireActiveMember());
  app2.use("/api/me/*", requireActiveMember());
  app2.use("/api/avatars/*", requireActiveMember());
  app2.use("/api/notifications/*", requireActiveMember());
  app2.use("/api/modules/:id/token", requireActiveMember());
  app2.use("/api/admin/*", requireAdmin());
  app2.get("/api/health", (c) => c.json({ ok: true, service: "workbench" }));
  registerProfileRoutes(app2, dependencies);
  registerAvatarRoutes(app2, dependencies);
  const routes = app2;
  registerAuthRoutes(routes);
  registerSetupRoutes(routes);
  registerMemberRoutes(routes, dependencies.createMailProvisioner, dependencies.createMailSender);
  registerInviteRoutes(routes, dependencies);
  registerActivateRoutes(routes, dependencies);
  registerModuleRoutes(routes);
  registerConnectRoutes(routes);
  registerModuleApiRoutes(app2);
  registerNotificationRoutes(routes);
  registerAuditRoutes(routes);
  registerSettingsRoutes(routes);
  registerMailTestRoutes(routes, dependencies);
  app2.notFound((c) => {
    const path = new URL(c.req.url).pathname;
    if (path.startsWith("/api/") || path === "/api" || path.startsWith("/.well-known/")) {
      return c.json({ error: "not found" }, 404);
    }
    return c.text("404 Not Found", 404);
  });
  return app2;
}

// src/asset-response.ts
function normalizeAssetResponse(response, pathname) {
  if (response.status !== 200) return response;
  const type = (response.headers.get("content-type") ?? "").split(";")[0]?.trim().toLowerCase() ?? "";
  if (type && type !== "application/octet-stream") return response;
  let contentType;
  if (/\.(?:m?js)$/i.test(pathname)) contentType = "text/javascript; charset=utf-8";
  else if (/\.css$/i.test(pathname)) contentType = "text/css; charset=utf-8";
  else if (/^(?:\/|\/index\.html|\/setup\/?|\/login\/?|\/app-password\/?|\/admin(?:\/.*)?|\/(?:invite|activate)\/[^/]+)$/.test(pathname)) {
    contentType = "text/html; charset=utf-8";
  }
  if (!contentType) return response;
  const headers = new Headers(response.headers);
  headers.set("content-type", contentType);
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
}

